it=value.unit, claim.raw_value=value.raw_value, claim.source_field=value.source_field, claim.source_release=$release, claim.source_id='avonet', claim.taxonomy_release=$taxonomy_release, claim.inferred=value.inferred, claim.evidence_kind=value.evidence_kind, claim.summary_statistic=value.summary_statistic, claim.retrieved_at=$retrieved_at MERGE (claim)-[:ASSERTS_ABOUT]->(taxon) MERGE (claim)-[:SUPPORTED_BY]->(evidence) MERGE (run)-[:INGESTED]->(claim) RETURN count(*) AS loaded_claims } CALL { WITH run,row,taxa,record WITH run,row,record,taxa WHERE size(taxa)<>1 MERGE (candidate:TaxonMappingCandidate {id:row.id+':candidate:'+$taxonomy_release}) SET candidate.source_scientific_name=row.scientific_name, candidate.source_taxonomy='HBW-BirdLife v5', candidate.taxonomy_release=$taxonomy_release, candidate.resolution_status='open', candidate.reason_code=CASE WHEN size(taxa)=0 THEN 'no_exact_match' ELSE 'ambiguous_exact_match' END, candidate.profile_json=row.profile_json MERGE (record)-[:HAS_MAPPING_CANDIDATE]->(candidate) MERGE (run)-[:QUARANTINED]->(candidate) RETURN count(*) AS loaded_candidates } RETURN $batch_index AS batch_index, $batch_count AS batch_count, count(*) AS loaded_profiles, sum(loaded_claims) AS loaded_claims, sum(loaded_candidates) AS loaded_candidates, sum(CASE WHEN size(taxa)=1 THEN 1 ELSE 0 END) AS matched_profiles, sum(CASE WHEN size(taxa)=1 THEN size(row.claims) ELSE 0 END) AS expected_claims".replace(/\$([A-Za-z_][A-Za-z0-9_]*)/g, (_, key) => values[key]); })() }}

